"use client";
import type { ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./bars-morph.css";

export type BarsShape = "menu" | "close" | "plus" | "minus" | "back" | "forward";

export type BarsMorphProps = Omit<ComponentProps<"span">, "children"> & {
  /** The glyph to show. Change it and the three bars move into the new shape. */
  shape: BarsShape;
};

/**
 * One icon made of three bars that turn into one another: a menu becomes a cross, a plus becomes a minus, an
 * arrow points the other way. Because the same three bars are always on screen, a toggle reads as one thing
 * changing state instead of one icon being swapped for another. Place it inside a button and name the button;
 * the glyph itself is hidden from assistive technology. The bars take the text colour. Under reduced motion the
 * shape changes without travelling.
 */
export function BarsMorph({ shape, className, ...props }: BarsMorphProps) {
  return (
    <span data-slot="bars-morph" data-shape={shape} aria-hidden="true" className={cn("relative inline-block size-5 shrink-0", className)} {...props}>
      <i />
      <i />
      <i />
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* bars-morph.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Bars morph: three bars take per-shape offsets, turns and lengths; arrow heads are the outer bars at 45 degrees. */
  [data-slot="bars-morph"] i { position: absolute; inset: calc(50% - 1px) 2px auto; height: 2px; border-radius: 1px; background: currentColor; transition: translate var(--duration-deliberate) var(--ease-settle), rotate var(--duration-deliberate) var(--ease-settle), scale var(--duration-deliberate) var(--ease-settle), opacity var(--duration-normal) var(--ease-out); }
  [data-slot="bars-morph"][data-shape="menu"] i:nth-child(1) { translate: 0 -6px; }
  [data-slot="bars-morph"][data-shape="menu"] i:nth-child(3) { translate: 0 6px; }
  [data-slot="bars-morph"][data-shape="close"] i:nth-child(1) { rotate: 45deg; }
  [data-slot="bars-morph"][data-shape="close"] i:nth-child(3) { rotate: -45deg; }
  [data-slot="bars-morph"]:is([data-shape="close"], [data-shape="minus"]) i:nth-child(2) { scale: 0 1; opacity: 0; }
  [data-slot="bars-morph"][data-shape="plus"] i:nth-child(2) { rotate: 90deg; }
  [data-slot="bars-morph"]:is([data-shape="plus"], [data-shape="minus"]) i:nth-child(3) { scale: 0 1; opacity: 0; }
  [data-slot="bars-morph"][data-shape="back"] i:nth-child(1) { translate: -4.6px -3.4px; rotate: -45deg; scale: 0.6 1; }
  [data-slot="bars-morph"][data-shape="back"] i:nth-child(3) { translate: -4.6px 3.4px; rotate: 45deg; scale: 0.6 1; }
  [data-slot="bars-morph"][data-shape="forward"] i:nth-child(1) { translate: 4.6px -3.4px; rotate: 45deg; scale: 0.6 1; }
  [data-slot="bars-morph"][data-shape="forward"] i:nth-child(3) { translate: 4.6px 3.4px; rotate: -45deg; scale: 0.6 1; }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="bars-morph"] i { transition: none; }
  }
}
